/**
 * Highest number the project has ever issued, whether the row that carried it
 * is live, archived or has moved away. The row scan only matters for projects
 * that predate `issue_number_sequences`; the stored mark is never lower.
 */
function highestIssuedNumber(orgId: OrgId, projectId: ProjectId): number {
  const stored = getDb()
    .select({ value: issueNumberSequences.lastNumber })
    .from(issueNumberSequences)
    .where(
      and(
        orgPredicate(issueNumberSequences.orgId, orgId),
        eq(issueNumberSequences.projectId, projectId),
      ),
    )
    .get();
  const seen = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return Math.max(stored?.value ?? 0, seen?.value ?? 0);
}

/** Records that `issueNumber` has been issued in the project. Never lowers the mark. */
function recordIssuedNumber(
  orgId: OrgId,
  projectId: ProjectId,
  issueNumber: number,
): void {
  getDb()
    .insert(issueNumberSequences)
    .values({ orgId, projectId, lastNumber: issueNumber })
    .onConflictDoUpdate({
      target: issueNumberSequences.projectId,
      set: {
        lastNumber: sql`max(${issueNumberSequences.lastNumber}, ${issueNumber})`,
      },
    })
    .run();
}

/**
 * Next per-project issue number: one above the highest number the project has
 * ever issued. Numbers are never reused, so an archived issue, or one moved to
 * another project, keeps its number reserved.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  return highestIssuedNumber(orgId, projectId) + 1;
}

