/**
 * Moves an issue into `toProjectId` under `toNumber`, a number the caller took
 * from the target's sequence. The number it leaves behind stays issued in the
 * source project, so it is never handed out there again (ADR 0011).
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issue: Issue,
  toProjectId: ProjectId,
  toNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId: toProjectId,
      number: toNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issue.id)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issue.id} not found`);

  recordIssuedNumber(orgId, issue.projectId, issue.number);
  recordIssuedNumber(orgId, toProjectId, toNumber);

  const labels = await listLabelsForIssues(orgId, [issue.id]);
  return toIssue(row, (labels[issue.id] ?? []).map((label) => label.id));
}

