/**
 * Moving an issue to another project of the same workspace (ADR 0011): what
 * stays, which number it takes, who may move it and what is announced.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as activityService from "@/server/services/activity-service";
import { NotFoundError } from "@/server/services/_support";
import * as issueService from "@/server/services/issue-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Project } from "@/types/project";
import type { Actor } from "@/types/member";

let cleanup: () => void;
let tenant: Tenant;
let listeners: Unsubscribe[];
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("movesvc");
  listeners = [
    activityService.registerActivityListeners(),
    searchService.registerSearchListeners(),
  ];
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  for (const off of listeners) off();
  cleanup();
});

/** A fresh project per test, so each test controls its own numbering. */
function newProject(key: string): Promise<Project> {
  return projectRepo.insertProject({
    orgId: tenant.org.id,
    name: `Project ${key}`,
    slug: key.toLowerCase(),
    key,
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  });
}

function createIn(projectId: Project["id"], title: string): Promise<Issue> {
  return issueService.createIssue(
    tenant.actors.member,
    issueInput(tenant.org.id, projectId, { title }),
  );
}

function moveTo(
  actor: Actor,
  issue: Issue,
  toProjectId: Project["id"],
): Promise<Issue> {
  return issueService.moveIssueToProject(actor, {
    orgId: tenant.org.id,
    issueId: issue.id,
    toProjectId,
  });
}

describe("services/issue-service — moveIssueToProject", () => {
  it("keeps the issue's content and gives it the target's next number", async () => {
    const source = await newProject("MVA");
    const target = await newProject("MVB");
    const issue = await createIn(source.id, "Keep everything I am");
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "in_progress",
    });
    await issueService.updateIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      description: "Details",
      priority: "high",
      estimate: 3,
    });
    await issueService.assignIssue(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
    });
    const { issue: before } = await issueService.getIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    const after = await moveTo(tenant.actors.member, issue, target.id);

    expect(after).toEqual({
      ...before,
      projectId: target.id,
      number: 1,
      updatedAt: after.updatedAt,
    });
    await expect(issueRepo.findIssueById(tenant.org.id, issue.id)).resolves.toEqual(after);
  });

  it("retires the number it leaves, so the source never issues it again", async () => {
    const source = await newProject("MVC");
    const target = await newProject("MVD");
    await createIn(source.id, "First in source");
    const second = await createIn(source.id, "Second in source");

    const moved = await moveTo(tenant.actors.member, second, target.id);
    expect(moved.number).toBe(1);

    const third = await createIn(source.id, "Third in source");
    expect(third.number).toBe(3);

    // Moving back takes a fresh number; the 2 it carried away stays retired.
    const back = await moveTo(tenant.actors.member, moved, source.id);
    expect(back.number).toBe(4);
  });

  it("publishes exactly one issue.moved, naming both projects and both numbers", async () => {
    const source = await newProject("MVE");
    const target = await newProject("MVF");
    const issue = await createIn(source.id, "Announce me");

    const moved = capture("issue.moved");
    const updated = capture("issue.updated");
    const created = capture("issue.created");
    const archived = capture("issue.archived");

    await moveTo(tenant.actors.member, issue, target.id);

    expect(moved).toEqual([
      {
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        occurredAt: expect.any(String),
        issueId: issue.id,
        fromProjectId: source.id,
        toProjectId: target.id,
        fromNumber: 1,
        toNumber: 1,
      },
    ]);
    expect(updated).toHaveLength(0);
    expect(created).toHaveLength(0);
    expect(archived).toHaveLength(0);
  });

  it("is a no-op within the same project and publishes nothing", async () => {
    const project = await newProject("MVG");
    const issue = await createIn(project.id, "Stay put");

    const moved = capture("issue.moved");
    const updated = capture("issue.updated");

    const same = await moveTo(tenant.actors.member, issue, project.id);

    expect(same).toEqual(issue);
    expect(moved).toHaveLength(0);
    expect(updated).toHaveLength(0);

    const next = await createIn(project.id, "Next one");
    expect(next.number).toBe(issue.number + 1);
  });

  it("refuses an actor who may not create issues in the target, changing nothing", async () => {
    const source = await newProject("MVH");
    const target = await newProject("MVI");
    const issue = await createIn(source.id, "Viewer cannot move me");

    const moved = capture("issue.moved");

    await expect(
      moveTo(tenant.actors.viewer, issue, target.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const stored = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stored?.projectId).toBe(source.id);
    expect(stored?.number).toBe(issue.number);
    expect(moved).toHaveLength(0);
  });

  it("refuses a move into a project already at its plan quota, changing nothing", async () => {
    const org = await createTenant("movequota", "free");
    const full = await projectRepo.insertProject({
      orgId: org.org.id,
      name: "Full",
      slug: "full",
      key: "FULL",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    // The free plan allows 100 issues per project.
    for (let number = 1; number <= 100; number += 1) {
      await issueRepo.insertIssue(
        issueInput(org.org.id, full.id, { title: `Seed ${number}` }),
        org.userIds.member,
        number,
      );
    }
    const issue = await issueService.createIssue(
      org.actors.member,
      issueInput(org.org.id, org.project.id, { title: "Wants in" }),
    );

    await expect(
      issueService.moveIssueToProject(org.actors.member, {
        orgId: org.org.id,
        issueId: issue.id,
        toProjectId: full.id,
      }),
    ).rejects.toThrow(/allows no more issues/);

    const stored = await issueRepo.findIssueById(org.org.id, issue.id);
    expect(stored?.projectId).toBe(org.project.id);
    expect(stored?.number).toBe(1);
  });

  it("refuses to move an archived issue", async () => {
    const source = await newProject("MVJ");
    const target = await newProject("MVK");
    const issue = await createIn(source.id, "Already archived");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      moveTo(tenant.actors.member, issue, target.id),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });

  it("refuses a target project that belongs to another workspace", async () => {
    const other = await createTenant("movecross");
    const source = await newProject("MVL");
    const issue = await createIn(source.id, "Stays home");

    await expect(
      moveTo(tenant.actors.member, issue, other.project.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("records one audit row under the target and leaves earlier history in the source", async () => {
    const source = await newProject("MVM");
    const target = await newProject("MVN");
    const issue = await createIn(source.id, "Audit me");

    await moveTo(tenant.actors.member, issue, target.id);

    const history = await activityRepo.listActivityForSubject(
      tenant.org.id,
      "issue",
      issue.id,
    );
    const created = history.find((event) => event.action === "issue.created");
    const moves = history.filter((event) => event.action === "issue.moved");

    expect(created?.projectId).toBe(source.id);
    expect(moves).toHaveLength(1);
    expect(moves[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "issue",
      subjectId: issue.id,
      projectId: target.id,
      metadata: {
        fromProjectId: source.id,
        toProjectId: target.id,
        fromNumber: 1,
        toNumber: 1,
      },
    });
  });

  it("moves the issue's search entry into the target project", async () => {
    const source = await newProject("MVO");
    const target = await newProject("MVP");
    const issue = await createIn(source.id, "Relocatable widget");

    const search = (projectId: Project["id"]) =>
      searchRepo.searchDocuments({
        orgId: tenant.org.id,
        q: "Relocatable",
        kinds: ["issue"],
        projectId,
        limit: 25,
        cursor: null,
      });

    expect((await search(source.id)).items.map((row) => row.subjectId)).toEqual([
      issue.id,
    ]);

    await moveTo(tenant.actors.member, issue, target.id);

    expect((await search(source.id)).items).toEqual([]);
    expect((await search(target.id)).items.map((row) => row.subjectId)).toEqual([
      issue.id,
    ]);
  });
});

